        "scopeSearch": "이름 또는 그룹으로 검색…",
        "scopeEmpty": "비어 있음",
        "scopeViaGroup": "그룹 경유",
        "scopeNothingSelected": "아직 체크한 항목이 없어요. 사용자는 직접 만든 항목만 볼 수 있어요.",
        "helpTitle": "접근 권한 작동 방식",
        "permissionsLegend": "“전체”는 섹션의 모든 항목을 보고 변경할 수 있어요. “읽기 전용”은 모든 항목을 보지만 변경은 할 수 없어요. “+ 선택 항목” 옵션은 체크한 그룹과 항목, 그리고 사용자가 만든 항목에만 적용돼요. “접근 불가”는 섹션을 숨겨요.",
        "helpRolesTitle": "두 가지 역할",
        "helpRolesText": "관리자는 모든 것을 보고 할 수 있으며, 권한은 관리자에게 적용되지 않아요. 사용자는 권한 설정에서 부여받은 것만 사용할 수 있어요. 사용자 행의 방패 아이콘에서 설정해요.",
        "helpLevelsTitle": "섹션의 접근 수준",
        "helpLevelsText": "“전체”는 모든 것을 보고 변경할 수 있어요. “읽기 전용”은 모든 것을 보지만 만들거나, 변경하거나, 삭제할 수 없어요. “접근 불가”는 메뉴에서 섹션을 숨기고 서버에서도 접근을 막아요.",
        "helpSelectedTitle": "“전체 + 선택 항목”과 “읽기 전용 + 선택 항목”",
        "helpSelectedText": "캠페인, 오퍼, 랜딩, 도메인에서 사용할 수 있어요. 사용자는 체크한 그룹, 체크한 개별 항목, 그리고 직접 만든 항목만 볼 수 있어요. 그 밖의 항목은 사용자에게 존재하지 않아요. 목록에 나타나지 않고, 직접 링크로도 열리지 않아요. “읽기 전용” 모드에서는 자신이 만든 항목을 포함해 아무것도 변경할 수 없어요.",
        "helpGroupsTitle": "그룹은 실시간으로 적용돼요",
        "helpGroupsText": "그룹에 권한을 주면 사용자는 지금 그 그룹에 있는 모든 항목과 나중에 추가되는 항목을 볼 수 있어요. 항목을 그룹에서 빼면 사용자에게서도 사라져요. 그룹 전체를 열지 않고 다른 사람의 그룹에서 개별 항목만 부여할 수도 있어요.",
        "helpLimitsTitle": "“선택 항목” 사용자가 할 수 없는 것",
        "helpLimitsText": "그룹을 만들거나, 이름을 바꾸거나, 삭제할 수 없어요. 자신이 만들지 않은 항목을 다른 그룹으로 옮길 수 없어요. 권한을 받지 않은 오퍼, 랜딩, 도메인을 자신의 캠페인에 추가할 수 없어요(관리자가 이미 연결해 둔 항목은 그대로 남아요). 도메인 페이지에서는 등록 업체, 가져오기, 전체 도메인 확인 기능을 사용할 수 없어요.",
        "helpStatsTitle": "통계",
        "helpStatsText": "대시보드, 리포트, 전환, 로그에는 사용자가 접근할 수 있는 캠페인의 데이터만 표시돼요.",
        "helpFinanceTitle": "재무 데이터",
        "helpFinanceText": "권한 설정 창 하단의 체크박스를 켜면 모든 표와 리포트에서 비용, 수익, 지급액이 숨겨져요. 이 숫자들은 서버에서 아예 전송되지 않아요.",
        "helpTemplatesTitle": "역할 템플릿",
        "helpTemplatesText": "새 사용자를 위한 기본 설정이에요. 미디어 바이어는 트래픽 관련 섹션이 전체 권한이고, 도메인과 로그는 읽기 전용이며, 재무 정보를 볼 수 있어요. 크리에이티브 디자이너는 랜딩과 미디어가 전체 권한이고, 나머지는 닫혀 있으며, 재무 정보는 숨겨져요. 개발자는 랜딩, 푸시, 로그가 전체 권한이고, 나머지는 읽기 전용이며, 재무 정보는 숨겨져요. 사용자 지정은 아무것도 채우지 않아요. 직접 만든 프리셋은 저장할 수 없어요. 설정은 한 번 적용되면 그 사용자에게 저장되므로, 이후에는 방패 아이콘으로 수정하세요.",
        "helpOffboardTitle": "팀을 떠난 사람",
        "helpOffboardText": "계정을 삭제하면 사용자는 다음 동작 때 패널에서 로그아웃되고, API 키도 작동을 멈춰요. 권한 변경은 다시 로그인하지 않아도 즉시 적용돼요.",
        "mcpTitle": "AI 어시스턴트 연결 (MCP)",
