        "oauthNotConfiguredTitle": "1클릭 OAuth에는 앱 인증 정보가 필요해요",
        "oauthNotConfiguredHint": "1클릭 로그인 버튼에는 직접 만든 TikTok for Business 개발자 앱의 App ID와 App Secret이 필요해요 (무료, 아래 가이드 참고). 개발자 앱이 없다면 “TikTok MCP로 연결” 버튼을 대신 사용하세요. 이 방법은 앱이 전혀 필요 없어요.",
        "tokenHowTo": "TikTok 연동 가이드 및 키",
        "tokenHowToHint": "방법 1: 직접 토큰 연결 (무료 TikTok 개발자 앱 필요, 방법 2의 1단계 참고)\n1. 앱이 승인되면 개발자 포털(business-api.tiktok.com → 앱 → Authorization)에서 장기 액세스 토큰을 생성하세요. 참고로 Events Manager의 토큰은 작동하지 않아요. 전환 이벤트만 보낼 수 있고 광고비는 읽을 수 없어요.\n2. ads.tiktok.com의 계정 전환 메뉴에서 숫자로 된 광고주 ID를 복사하세요.\n3. 아래에 액세스 토큰과 광고주 ID를 붙여넣고 “연결 테스트” → “저장”을 누르세요.\n\n방법 2: 1클릭 OAuth (모든 계정과 픽셀 자동 검색)\n1. TikTok for Business 개발자 포털(business-api.tiktok.com → Apps & Agents)에서 Direct Advertiser로 등록(무료)하고, Ads Management 및 Reporting 권한을 가진 앱을 만드세요. 승인에는 보통 몇 시간에서 이틀 정도 걸려요.\n2. Authorized Redirect URI에 트래커 URL을 입력하세요 (HTTPS 필수):\n{redirect_uri}\n3. 아래에 App ID와 App Secret을 입력하세요 (또는 .env 파일에 ORBITRA_TIKTOK_APP_ID와 ORBITRA_TIKTOK_APP_SECRET을 설정하세요).\n4. 저장하면 1클릭 로그인으로 모든 계정을 자동으로 찾고 픽셀을 한 번에 가져와요.",
